	fakeGitHub = "ghp_" + "R7mK2xQ9vLp4Tz8NwY3bHc6JdF1sGa5Ue0Vi"
	fakeSlack  = "xoxb" + "-2210391-8812736123-kTz9QwLm4Rv"
	fakeStripe = "sk_live_" + "51Hx9QkLm2Vn8Rt4Yw6Zp3Bc"
