	fakeAPIKey = "hT9q/Lm" + "2+Zx8Vb4Nc7Rk1Wp5Ys3Df6Gj0Qa2Eu8I"
	fakeJWT    = "eyJ" + "hbGciOiJIUzI1NiJ9.eyJzdWIiOiJkZW1vIn0.Xk3vQ9mZpL2rT8wY4nB6cH1jF5sD0aGe"
