// Command leakscan finds secrets in dirs & git history.
package main

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"os/signal"
	"path/filepath"

	"github.com/rezmoss/leakscan/scan"
)

const usage = `usage: leakscan <dir|git> [flags] [path]

  dir   scan files in a directory (default ".")
  git   scan added lines in all git history (default ".")

flags:
`

// exit: 0 clean, 1 findings, 2 err
func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)
	defer stop()

	n, err := run(ctx, os.Args[1:], os.Stdout)
	if err != nil {
		fmt.Fprintln(os.Stderr, "leakscan:", err)
		os.Exit(2)
	}
	if n > 0 {
		os.Exit(1)
	}
}

type options struct {
	mode       string
	root       string
	format     string
	ignorePath string
	entropy    float64
}

func parseArgs(args []string) (options, error) {
	fs := flag.NewFlagSet("leakscan", flag.ContinueOnError)
	opts := options{root: "."}
	fs.StringVar(&opts.format, "format", "text", "output format: text, json or sarif")
	fs.StringVar(&opts.ignorePath, "ignore", "", "fingerprint ignore file (default <path>/.leakscanignore)")
	fs.Float64Var(&opts.entropy, "entropy", scan.DefaultMinEntropy, "min entropy for generic secrets")
	fs.Usage = func() {
		fmt.Fprint(fs.Output(), usage)
		fs.PrintDefaults()
	}

	if len(args) == 0 {
		fs.Usage()
		return opts, errors.New("missing command")
	}
	opts.mode = args[0]
	if opts.mode != "dir" && opts.mode != "git" {
		fs.Usage()
		return opts, fmt.Errorf("unknown command %q", opts.mode)
	}
	if err := fs.Parse(args[1:]); err != nil {
		return opts, err
	}
	if fs.NArg() > 0 {
		opts.root = fs.Arg(0)
	}
	if opts.ignorePath == "" {
		opts.ignorePath = filepath.Join(opts.root, ".leakscanignore")
	}
	return opts, nil
}

// returns # findings
func run(ctx context.Context, args []string, stdout io.Writer) (int, error) {
	opts, err := parseArgs(args)
	if errors.Is(err, flag.ErrHelp) {
		return 0, nil
	}
	if err != nil {
		return 0, err
	}
	write, ok := writers[opts.format]
	if !ok {
		return 0, fmt.Errorf("unknown format %q", opts.format)
	}

	d := scan.NewDetector()
	d.MinEntropy = opts.entropy

	var findings []scan.Finding
	switch opts.mode {
	case "git":
		findings, err = d.ScanGit(ctx, opts.root)
	case "dir":
		findings, err = d.ScanDir(ctx, opts.root)
	}
	if err != nil {
		return 0, err
	}

	ignore, err := scan.LoadIgnore(opts.ignorePath)
	if err != nil {
		return 0, err
	}
	findings = ignore.Filter(findings)
	scan.SortFindings(findings)

	return len(findings), write(stdout, findings, d.Rules)
}

var writers = map[string]func(io.Writer, []scan.Finding, []scan.Rule) error{
	"text":  func(w io.Writer, f []scan.Finding, _ []scan.Rule) error { return scan.WriteText(w, f) },
	"json":  func(w io.Writer, f []scan.Finding, _ []scan.Rule) error { return scan.WriteJSON(w, f) },
	"sarif": scan.WriteSARIF,
}

package scan

import "math"

// Entropy: Shannon, bits/byte.
func Entropy(s string) float64 {
	if s == "" {
		return 0
	}
	var counts [256]int
	for i := range len(s) {
		counts[s[i]]++
	}
	n := float64(len(s))
	var h float64
	for _, c := range counts {
		if c == 0 {
			continue
		}
		p := float64(c) / n
		h -= p * math.Log2(p)
	}
	return h
}

package scan

import (
	"bufio"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"strings"
)

// Finding: Commit empty for dir scans.
type Finding struct {
	RuleID      string `json:"rule"`
	Description string `json:"description"`
	File        string `json:"file"`
	Line        int    `json:"line"`
	Column      int    `json:"column"`
	Commit      string `json:"commit,omitempty"`
	Redacted    string `json:"secret"`
	Fingerprint string `json:"fingerprint"`
}

func newFinding(m Match, file string, line int, commit string) Finding {
	sum := sha256.Sum256([]byte(commit + "\x00" + file + "\x00" + m.Rule.ID + "\x00" + m.Secret))
	return Finding{
		RuleID:      m.Rule.ID,
		Description: m.Rule.Description,
		File:        file,
		Line:        line,
		Column:      m.Column,
		Commit:      commit,
		Redacted:    Redact(m.Secret),
		Fingerprint: hex.EncodeToString(sum[:8]),
	}
}

// Redact keeps 1st 4 chars if long.
func Redact(secret string) string {
	if len(secret) < 12 {
		return strings.Repeat("*", 8)
	}
	return secret[:4] + strings.Repeat("*", 8)
}

// Ignore: fingerprints to skip.
type Ignore map[string]bool

// LoadIgnore: 1 fp/line, # comments ok, missing file = empty.
func LoadIgnore(path string) (Ignore, error) {
	f, err := os.Open(path)
	if errors.Is(err, fs.ErrNotExist) {
		return Ignore{}, nil
	}
	if err != nil {
		return nil, err
	}
	defer f.Close()

	ig := Ignore{}
	s := bufio.NewScanner(f)
	for s.Scan() {
		line, _, _ := strings.Cut(s.Text(), "#")
		if line = strings.TrimSpace(line); line != "" {
			ig[line] = true
		}
	}
	if err := s.Err(); err != nil {
		return nil, fmt.Errorf("read %s: %w", path, err)
	}
	return ig, nil
}

func (ig Ignore) Filter(findings []Finding) []Finding {
	kept := findings[:0]
	for _, f := range findings {
		if !ig[f.Fingerprint] {
			kept = append(kept, f)
		}
	}
	return kept
}

package scan

import "regexp"

// Rule: Regex needs exactly 1 capture group (secret).
// Keywords: lowercase prefilter before regex.
type Rule struct {
	ID           string
	Description  string
	Keywords     []string
	Regex        *regexp.Regexp
	CheckEntropy bool
}

var DefaultRules = []Rule{
	{
		ID:          "aws-access-key-id",
		Description: "AWS access key ID",
		Keywords:    []string{"akia", "asia"},
		Regex:       regexp.MustCompile(`\b((?:AKIA|ASIA)[0-9A-Z]{16})\b`),
	},
	{
		ID:          "github-token",
		Description: "GitHub personal access or app token",
		Keywords:    []string{"ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_"},
		Regex:       regexp.MustCompile(`\b(gh[pousr]_[A-Za-z0-9]{36,255}|github_pat_[A-Za-z0-9_]{82})\b`),
	},
	{
		ID:          "slack-token",
		Description: "Slack token",
		Keywords:    []string{"xox"},
		Regex:       regexp.MustCompile(`\b(xox[abposr]-[A-Za-z0-9-]{10,})`),
	},
	{
		ID:          "stripe-live-key",
		Description: "Stripe live secret or restricted key",
		Keywords:    []string{"sk_live_", "rk_live_"},
		Regex:       regexp.MustCompile(`\b((?:sk|rk)_live_[A-Za-z0-9]{24,})\b`),
	},
	{
		ID:          "private-key",
		Description: "Private key block",
		Keywords:    []string{"private key"},
		Regex:       regexp.MustCompile(`(-----BEGIN (?:RSA |EC |DSA |OPENSSH |PGP |ENCRYPTED )?PRIVATE KEY(?: BLOCK)?-----)`),
	},
	{
		ID:           "generic-secret",
		Description:  "Generic secret assigned to a key, token or password variable",
		Keywords:     []string{"key", "secret", "token", "passw"},
		Regex:        regexp.MustCompile(`(?i)(?:api[_-]?key|secret|token|passw(?:or)?d)\w*["']?\s*[:=]\s*["']?([A-Za-z0-9_\-+/=.]{8,})`),
		CheckEntropy: true,
	},
}

package scan

import (
	"regexp"
	"slices"
	"strings"
)

// DefaultMinEntropy: min for CheckEntropy rules.
const DefaultMinEntropy = 3.5

type Match struct {
	Rule   *Rule
	Secret string
	Column int

	start, end int
}

type Detector struct {
	Rules      []Rule
	MinEntropy float64
}

func NewDetector() *Detector {
	return &Detector{Rules: DefaultRules, MinEntropy: DefaultMinEntropy}
}

// Find: span reported once, so specific rules go before generic.
func (d *Detector) Find(line string) []Match {
	lower := strings.ToLower(line)
	var matches []Match
	for i := range d.Rules {
		r := &d.Rules[i]
		if !slices.ContainsFunc(r.Keywords, func(k string) bool { return strings.Contains(lower, k) }) {
			continue
		}
		for _, loc := range r.Regex.FindAllStringSubmatchIndex(line, -1) {
			start, end := loc[2], loc[3]
			if overlaps(matches, start, end) {
				continue
			}
			secret := line[start:end]
			if r.CheckEntropy && (Entropy(secret) < d.MinEntropy || looksLikeCode(line, start, end)) {
				continue
			}
			matches = append(matches, Match{Rule: r, Secret: secret, Column: start + 1, start: start, end: end})
		}
	}
	return matches
}

func overlaps(matches []Match, start, end int) bool {
	return slices.ContainsFunc(matches, func(m Match) bool {
		return start < m.end && m.start < end
	})
}

var (
	plainIdent  = regexp.MustCompile(`^[A-Za-z_]+$`)
	dottedIdent = regexp.MustCompile(`^[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)+$`)
	constIdent  = regexp.MustCompile(`^[A-Z][A-Z0-9]*(?:_[A-Z0-9]+)+$`)
)

// looksLikeCode: call(), config.TokenStore, TOKEN_ALL_ACCESS.
// JWTs dotted too but start w/ "eyJ".
func looksLikeCode(line string, start, end int) bool {
	s := line[start:end]
	switch {
	case strings.HasPrefix(s, "eyJ"):
		return false
	case strings.HasPrefix(line[end:], "("):
		return true
	}
	return plainIdent.MatchString(s) || dottedIdent.MatchString(s) || constIdent.MatchString(s)
}

package scan

import (
	"bufio"
	"bytes"
	"context"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
)

// MaxFileSize: bigger files skipped.
const MaxFileSize = 10 << 20

// 64K default too small for minified js, lockfiles
const maxLineSize = 16 << 20

// ScanDir scans text files under root, skips .git
func (d *Detector) ScanDir(ctx context.Context, root string) ([]Finding, error) {
	var findings []Finding
	err := filepath.WalkDir(root, func(path string, e fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if err := ctx.Err(); err != nil {
			return err
		}
		if e.IsDir() {
			if e.Name() == ".git" {
				return filepath.SkipDir
			}
			return nil
		}
		found, err := d.scanEntry(root, path, e)
		findings = append(findings, found...)
		return err
	})
	return findings, err
}

func (d *Detector) scanEntry(root, path string, e fs.DirEntry) ([]Finding, error) {
	if !e.Type().IsRegular() {
		return nil, nil
	}
	info, err := e.Info()
	if err != nil {
		return nil, err
	}
	if info.Size() > MaxFileSize {
		return nil, nil
	}
	rel, err := filepath.Rel(root, path)
	if err != nil {
		return nil, err
	}
	return d.scanFile(path, filepath.ToSlash(rel))
}

func (d *Detector) scanFile(path, name string) ([]Finding, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	br := bufio.NewReader(f)
	if head, _ := br.Peek(8000); bytes.IndexByte(head, 0) >= 0 {
		return nil, nil
	}
	return d.scanLines(br, name)
}

func (d *Detector) scanLines(r io.Reader, name string) ([]Finding, error) {
	var findings []Finding
	s := bufio.NewScanner(r)
	s.Buffer(make([]byte, 0, 64<<10), maxLineSize)
	for n := 1; s.Scan(); n++ {
		for _, m := range d.Find(s.Text()) {
			findings = append(findings, newFinding(m, name, n, ""))
		}
	}
	if err := s.Err(); err != nil {
		return nil, fmt.Errorf("scan %s: %w", name, err)
	}
	return findings, nil
}

package scan

import (
	"cmp"
	"encoding/json"
	"fmt"
	"io"
	"slices"
	"strings"
	"text/tabwriter"
)

func WriteText(w io.Writer, findings []Finding) error {
	tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
	fmt.Fprintln(tw, "RULE\tLOCATION\tCOMMIT\tSECRET\tFINGERPRINT")
	for _, f := range findings {
		fmt.Fprintf(tw, "%s\t%s:%d\t%s\t%s\t%s\n",
			f.RuleID, f.File, f.Line, shortCommit(f.Commit), f.Redacted, f.Fingerprint)
	}
	if err := tw.Flush(); err != nil {
		return err
	}
	_, err := fmt.Fprintf(w, "\n%d finding(s)\n", len(findings))
	return err
}

func shortCommit(c string) string {
	if c == "" {
		return "-"
	}
	return c[:min(len(c), 8)]
}

func WriteJSON(w io.Writer, findings []Finding) error {
	enc := json.NewEncoder(w)
	enc.SetIndent("", "  ")
	return enc.Encode(nonNil(findings))
}

func nonNil(findings []Finding) []Finding {
	if findings == nil {
		return []Finding{}
	}
	return findings
}

type sarifLog struct {
	Version string     `json:"version"`
	Schema  string     `json:"$schema"`
	Runs    []sarifRun `json:"runs"`
}

type sarifRun struct {
	Tool    sarifTool     `json:"tool"`
	Results []sarifResult `json:"results"`
}

type sarifTool struct {
	Driver sarifDriver `json:"driver"`
}

type sarifDriver struct {
	Name           string      `json:"name"`
	InformationURI string      `json:"informationUri"`
	Rules          []sarifRule `json:"rules"`
}

type sarifRule struct {
	ID               string       `json:"id"`
	ShortDescription sarifMessage `json:"shortDescription"`
}

type sarifMessage struct {
	Text string `json:"text"`
}

type sarifResult struct {
	RuleID              string            `json:"ruleId"`
	Level               string            `json:"level"`
	Message             sarifMessage      `json:"message"`
	Locations           []sarifLocation   `json:"locations"`
	PartialFingerprints map[string]string `json:"partialFingerprints"`
}

type sarifLocation struct {
	PhysicalLocation sarifPhysical `json:"physicalLocation"`
}

type sarifPhysical struct {
	ArtifactLocation sarifArtifact `json:"artifactLocation"`
	Region           sarifRegion   `json:"region"`
}

type sarifArtifact struct {
	URI string `json:"uri"`
}

type sarifRegion struct {
	StartLine   int `json:"startLine"`
	StartColumn int `json:"startColumn,omitempty"`
}

// WriteSARIF: SARIF 2.1.0 for GH code scanning.
func WriteSARIF(w io.Writer, findings []Finding, rules []Rule) error {
	run := sarifRun{
		Tool: sarifTool{Driver: sarifDriver{
			Name:           "leakscan",
			InformationURI: "https://github.com/rezmoss/leakscan",
		}},
		Results: []sarifResult{},
	}
	for _, r := range rules {
		run.Tool.Driver.Rules = append(run.Tool.Driver.Rules, sarifRule{
			ID: r.ID, ShortDescription: sarifMessage{Text: r.Description},
		})
	}
	for _, f := range findings {
		msg := fmt.Sprintf("%s found: %s", f.Description, f.Redacted)
		if f.Commit != "" {
			msg += " (commit " + shortCommit(f.Commit) + ")"
		}
		run.Results = append(run.Results, sarifResult{
			RuleID:  f.RuleID,
			Level:   "error",
			Message: sarifMessage{Text: msg},
			Locations: []sarifLocation{{PhysicalLocation: sarifPhysical{
				ArtifactLocation: sarifArtifact{URI: f.File},
				Region:           sarifRegion{StartLine: max(f.Line, 1), StartColumn: f.Column},
			}}},
			PartialFingerprints: map[string]string{"leakscan/v1": f.Fingerprint},
		})
	}
	enc := json.NewEncoder(w)
	enc.SetIndent("", "  ")
	return enc.Encode(sarifLog{
		Version: "2.1.0",
		Schema:  "https://json.schemastore.org/sarif-2.1.0.json",
		Runs:    []sarifRun{run},
	})
}

func SortFindings(findings []Finding) {
	slices.SortStableFunc(findings, func(a, b Finding) int {
		return cmp.Or(
			strings.Compare(a.File, b.File),
			cmp.Compare(a.Line, b.Line),
			strings.Compare(a.RuleID, b.RuleID),
		)
	})
}

package scan

import (
	"bufio"
	"bytes"
	"context"
	"fmt"
	"io"
	"os/exec"
	"strconv"
	"strings"
	"time"
)

// NUL never in text diffs, no clash w/ content
const commitMarker = "\x00commit "

// ScanGit scans added lines, all commits, all refs.
func (d *Detector) ScanGit(ctx context.Context, repo string) ([]Finding, error) {
	cmd := exec.CommandContext(ctx, "git", "-C", repo,
		"-c", "core.quotePath=false",
		"log", "-p", "-U0", "--all", "--no-color", "--no-ext-diff", "--no-renames",
		"--format=%x00commit %H")
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	cmd.WaitDelay = 5 * time.Second
	out, err := cmd.StdoutPipe()
	if err != nil {
		return nil, err
	}
	if err := cmd.Start(); err != nil {
		return nil, fmt.Errorf("git start: %w", err)
	}

	findings, parseErr := d.parseLog(out)
	if parseErr != nil {
		// drain, else git blocks on full pipe
		io.Copy(io.Discard, out)
	}
	if err := cmd.Wait(); err != nil {
		return nil, fmt.Errorf("git log: %w: %s", err, strings.TrimSpace(stderr.String()))
	}
	return findings, parseErr
}

func (d *Detector) parseLog(r io.Reader) ([]Finding, error) {
	var (
		findings []Finding
		commit   string
		file     string
		line     int
		inHunk   bool
	)
	s := bufio.NewScanner(r)
	s.Buffer(make([]byte, 0, 64<<10), maxLineSize)
	for s.Scan() {
		text := s.Text()
		if hash, ok := strings.CutPrefix(text, commitMarker); ok {
			commit = hash
			file, inHunk = "", false
			continue
		}
		switch {
		case strings.HasPrefix(text, "diff --git "):
			file, inHunk = "", false
		case !inHunk && strings.HasPrefix(text, "+++ "):
			file = parseNewPath(text)
		case strings.HasPrefix(text, "@@ "):
			inHunk = true
			line = parseHunkStart(text)
		case inHunk && file != "" && strings.HasPrefix(text, "+"):
			for _, m := range d.Find(text[1:]) {
				findings = append(findings, newFinding(m, file, line, commit))
			}
			line++
		}
	}
	if err := s.Err(); err != nil {
		return nil, fmt.Errorf("read git log: %w", err)
	}
	return findings, nil
}

// parseNewPath: "+++ b/path" -> path, "" for deletions.
func parseNewPath(text string) string {
	path, ok := strings.CutPrefix(text, "+++ b/")
	if !ok {
		return ""
	}
	return path
}

// parseHunkStart: "@@ -10,2 +12,3 @@" -> 12.
func parseHunkStart(text string) int {
	_, rest, _ := strings.Cut(text, " +")
	rest, _, _ = strings.Cut(rest, " ")
	rest, _, _ = strings.Cut(rest, ",")
	n, err := strconv.Atoi(rest)
	if err != nil {
		return 0
	}
	return n
}
